// Hand-written designer for the main dashboard. Builds the sidebar nav, the
// 6 content pages (Status / Alerts / AI Threats / Settings / Logs / Console)
// and every static control. Code-behind file (DashboardForm.cs) handles the
// dynamic logic.
//
// This file is treated as auto-generated by the C# compiler because of the
// .Designer.cs naming convention. The `#nullable` directive below silences
// the CS8669 warnings that would otherwise fire on every `string?` field.

#nullable enable annotations

using System;
