    /// <summary>
    /// Builds one of the four big stat cards on the Status page. Returns the
    /// card panel and the inner Label that holds the metric so the
    /// code-behind can update it on every tick.
    /// </summary>
    private (Panel card, Label valueLabel) BuildStatCard(
        string headerText, string initialValue, Color accent, Point location)
    {
        var card = new Panel
        {
            Size      = new Size(200, 90),
            BackColor = Theme.Card,
            Location  = location,
            Cursor    = Cursors.Hand,
        };
        var bar = new Panel
        {
            Dock      = DockStyle.Left,
            Width     = 4,
            BackColor = accent,
        };
        card.Controls.Add(bar);

        var header = new Label
        {
            Text      = headerText,
            Font      = Theme.CardLabel(),
            ForeColor = Theme.TextDim,
            AutoSize  = true,
            Location  = new Point(16, 14),
        };
        var value = new Label
        {
            Text      = initialValue,
            Font      = Theme.CardValue(),
            ForeColor = Theme.TextMain,
            AutoSize  = true,
            Location  = new Point(16, 32),
        };
        card.Controls.Add(header);
        card.Controls.Add(value);

        // Hover effect
        void Hover(object? s, EventArgs e) => card.BackColor = Theme.CardHover;
        void Leave(object? s, EventArgs e) => card.BackColor = Theme.Card;
        card.MouseEnter   += Hover; card.MouseLeave   += Leave;
        header.MouseEnter += Hover; header.MouseLeave += Leave;
        value.MouseEnter  += Hover; value.MouseLeave  += Leave;

        return (card, value);
    }

